random.seed(0)
D=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday']
items=[];control=[]
for i in range(7):
    for L in (2,3,4,5,6):
        seq=[D[(i+j)%7] for j in range(L)]
        items.append({'prompt':'Days in order: '+', '.join(seq)+',','answer':' '+D[(i+L)%7]})
        items.append({'prompt':'Weekly schedule: '+', then '.join(seq)+', then','answer':' '+D[(i+L)%7]})
for t in range(70):
    s=random.randint(3,40); L=random.choice([2,3,4,5,6])
    if t%2: control.append({'prompt':'Numbers in order: '+', '.join(str(s+j) for j in range(L))+',','answer':' '+str(s+L)})
    else: control.append({'prompt':'Weekly schedule: '+', then '.join(str(s+j) for j in range(L))+', then','answer':' '+str(s+L)})
